//
//! A small signed/unsigned reference for methods generated by [`int!`].
//

#[cfg(feature = "_docs_examples")]
crate::int! {
    #[doc = crate::_tags!(example num)]
    /// Demonstrates integer operations generated by [`int!`][crate::int].
    #[doc = crate::_doc_meta!{
        location("num/dom/int", struct IntExample),
    }]
    /// Uses `i32` and `u32` as representative signed and unsigned carriers;
    /// the macro supports all primitive integer widths.
    ///
    /// # Signed
    /// ```
    /// use devela::IntExample;
    /// type I = IntExample<i32>;
    /// assert_eq!(I::new(-128).digits().get(), 3);
    /// assert_eq!(I::new(-128).digits_sign().get(), 4);
    /// assert_eq!(I::new(-128).digits_base(I::new(2)).get(), 8);
    /// assert_eq!(I::new(-128).digits_base_sign(I::new(2)).get(), 9);
    /// assert_eq!(I::new(-128).digital_root().get(), 2);
    /// assert_eq!(I::new(-33).digital_root_base(I::new(16)).get(), 3);
    /// ```
    /// # Unsigned
    /// ```
    /// use devela::IntExample;
    /// type U = IntExample<u32>;
    /// assert_eq!(U::new(127).digits().get(), 3);
    /// assert_eq!(U::new(127).digits_sign().get(), 3);
    /// assert_eq!(U::new(255).digits_base(U::new(16)).get(), 2);
    /// assert_eq!(U::new(255).digits_base_sign(U::new(16)).get(), 2);
    /// assert_eq!(U::new(126).digital_root().get(), 9);
    /// assert_eq!(U::new(33).digital_root_base(U::new(16)).get(), 3);
    /// ```
    pub struct IntExample: <> impl (i32, u32);
    ops(base);
}

#[cfg(test)]
mod _test {
    use crate::int;

    int! { struct Example: <> impl (i32, u32); ops(base); }

    #[test]
    fn signed_unsigned() {
        assert_eq!(Example::<i32>::new(i32::MIN).digital_root().get(), 2);
        assert_eq!(Example::<u32>::new(255).digits_base(Example::<u32>::new(16)).get(), 2);
    }
}
